CREATE OR REPLACE FUNCTION public.wk_swap_item_atomic(p_user uuid,p_date date,p_id uuid,p_expected jsonb,p_target text,p_reason text,p_missing text[],p_scope text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.wk_prescriptions; t public.wk_movement_catalog; v_memory boolean:=false; v_tracking text; BEGIN PERFORM public.wk_lock_plan_day(p_user,p_date); IF p_scope NOT IN ('today','always') OR nullif(trim(p_reason),'') IS NULL THEN RAISE EXCEPTION 'Invalid swap'; END IF; SELECT * INTO r FROM public.wk_prescriptions WHERE id=p_id AND user_id=p_user AND plan_date=p_date FOR UPDATE; IF NOT FOUND OR r.status NOT IN ('planned','pending') OR to_jsonb(r)<>p_expected THEN RAISE EXCEPTION 'Plan changed'; END IF; IF EXISTS(SELECT 1 FROM public.wk_session_logs WHERE prescription_id=p_id) OR EXISTS(SELECT 1 FROM public.hammer_daily_task_completions WHERE user_id=p_user AND plan_date=p_date AND task_id=p_id::text AND completed) THEN RAISE EXCEPTION 'Already started'; END IF; SELECT * INTO t FROM public.wk_movement_catalog WHERE slug=p_target AND is_active IS TRUE AND superseded_by IS NULL; IF NOT FOUND OR t.slug=r.movement_slug THEN RAISE EXCEPTION 'Unavailable target'; END IF; SELECT payload->>'measure_type' INTO v_tracking FROM public.exercise_vault_versions WHERE slug=t.slug AND undone_at IS NULL AND effective_from<=p_date ORDER BY version DESC LIMIT 1; UPDATE public.wk_prescriptions SET movement_slug=t.slug,movement_name=t.name,why_payload=coalesce(why_payload,'{}'::jsonb)||jsonb_build_object('tracking_measure_type',v_tracking),substituted_from_slug=coalesce(substituted_from_slug,r.movement_slug),substitution_reason=p_reason,updated_at=clock_timestamp() WHERE id=p_id RETURNING * INTO r; INSERT INTO public.swap_log(user_id,plan_date,prescription_id,from_slug,to_slug,reason,missing_items,scope) VALUES(p_user,p_date,p_id,p_expected->>'movement_slug',t.slug,p_reason,coalesce(p_missing,'{}'),p_scope); IF cardinality(coalesce(p_missing,'{}'))>0 THEN INSERT INTO public.athlete_equipment_memory(user_id,request_id,scope,plan_date,confirmed_have,confirmed_lacks) VALUES(p_user,gen_random_uuid(),p_scope,p_date,'{}',p_missing); v_memory:=true; END IF; RETURN jsonb_build_object('saved',to_jsonb(r),'memorySaved',v_memory); END $$; REVOKE ALL ON FUNCTION public.wk_swap_item_atomic(uuid,date,uuid,jsonb,text,text,text[],text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.wk_swap_item_atomic(uuid,date,uuid,jsonb,text,text,text[],text) TO service_role; COMMENT ON FUNCTION public.wk_swap_item_atomic(uuid,date,uuid,jsonb,text,text,text[],text) IS 'plan-swap only; existing day-lock atomic save resolves target tracking effective on plan date without changing dose, rest, memory or access.';